INSERT INTO funding_opportunities (name, organization, description, opportunity_type, check_size_min, check_size_max, stage, sectors, website, location, is_active, chicago_focused, featured) VALUES
('Social venture capital', 'Social venture capital', 'Social venture capital is a form of investment funding that is usually funded by a group of social venture capitalists or an impact investor to provide seed-funding investment, usually in a for-profit social enterprise, in return to achieve an outsized gain in financial return while delivering socia', 'vc', NULL, NULL, ARRAY[]::text[], ARRAY[]::text[], 'https://en.wikipedia.org/wiki/Social_venture_capital', NULL, TRUE, FALSE, FALSE),
('Startup ecosystem', 'Startup ecosystem', 'A startup ecosystem is formed by people in startups in their various stages, and various types of organizations in a location (physical or virtual) that are interacting as a system to create and scale new startup companies. These organizations can be further divided into categories such as universit', 'vc', NULL, NULL, ARRAY[]::text[], ARRAY[]::text[], 'https://en.wikipedia.org/wiki/Startup_ecosystem', NULL, TRUE, FALSE, FALSE),
('SWORD-financing', 'SWORD-financing', 'SWORD-financing (stock and warrant off-balance sheet research & development financing) is a special form of financing invented to help junior biotech companies access institutional capital markets to finance their research and development (R&D) via establishing a special purpose entity and giving th', 'vc', NULL, NULL, ARRAY[]::text[], ARRAY[]::text[], 'https://en.wikipedia.org/wiki/SWORD-financing', NULL, TRUE, FALSE, FALSE),
('Tag-along right', 'Tag-along right', 'Tag along rights (TARs) comprise a group of clauses in a contract which together have the effect of allowing the minority shareholder(s) in a corporation to also take part in a sale of shares by the majority shareholder to a third party under the same terms and conditions.
